#!/usr/bin/env python3
import json

def a(href, text):
    return '<a href="%s" target="_blank" rel="noopener">%s</a>' % (href, text)
def p(html): return {'t': 'p', 'html': html}

JUGG = 'https://www.forbesindia.com/article/boardroom/dmart-the-juggernaut-continues-to-roll-for-indias-value-shop/48457/1'
BIO  = 'https://www.forbesindia.com/article/leaderboard/dmarts-founder-radhakishan-damani-the-unlikely-retail-billionaire/46469/1'
HIND = 'https://www.thehindu.com/business/d-mart-shares-double-on-day-of-debut/article17550588.ece'
ETJ  = 'https://economictimes.indiatimes.com/small-biz/entrepreneurship/radhakishan-damani-his-journey-from-dalal-street-punter-to-long-term-investor-to-entrepreneur/articleshow/58230305.cms'
ETM  = 'https://economictimes.indiatimes.com/radhakishan-damani-man-with-the-midas-touch-in-the-stock-markets/articleshow/32630959.cms'
NSE  = 'https://nsearchives.nseindia.com/corporate/FinalOutcomeOfBM11012025_11012025194333.pdf'
FY26 = 'https://api.dmartindia.com/corporate/content/file/v1/2/R2aWBiIpiuD39xgfm4wrqQKc1777723315/Press%20release%20dated%202nd%20May,%202026.pdf'
Q2   = 'https://www.storyboard18.com/brand-marketing/avenue-supermarts-q2-fy27-dmart-opens-15-stores-revenue-rises-18-to-rs-19644-crore-112314.htm'

lr = {
 'title': 'The purchase manager',
 'fact': "A Slow Burn long read, Tuesday 17 November 2026. India's most valuable grocery chain is run by a man who introduced himself to suppliers as its purchase manager. Radhakishan Damani built DMart out of a decade behind the counter of someone else's franchise, a rule about paying suppliers before anyone else, and a refusal to rent the floor he sold from. Avenue Supermarts, the company he incorporated in 2000, now runs 518 stores and did 66,968 crore rupees of standalone revenue in the year to March 2026 - and this February it changed chief executives without a ripple. This is the build story: the apprenticeship, the store, the hire, the machine, the sharing, the listing, and the discipline that outlived the founder's hand.",
 'groups': []
}
G = lr['groups']

G.append({'heading': '1. The counter', 'blocks': [
 p(' Before he was a retailer, Radhakishan Damani was the market\'s most careful student of other people\'s prices. He had joined his brother\'s stockbroking business at thirty-two, after their father\'s death, and through the late eighties he built his first fortune buying multinational consumer stocks - Gillette, VST Industries - while learning the short side of the ring from Manu Manek, the operator the street called the Cobra (' + a(ETM, 'the Economic Times\' profile') + '). The war that made his name was the two-year fight against Harshad Mehta\'s bull run: Damani and the bear cartel sold into prices they believed were fantasy, bled daily while the prices rose, and were carried out at a loss in the first round - then the scam broke in 1992, the market collapsed, and the shorts were vindicated. Years later he is believed to have told friends how close it ran: had Harshad held his position seven more days, he would have been on the road with a begging bowl - an attributed recollection, quoted as one (' + a(ETJ, 'the journey, from thirty marketmen') + '). After 1992 he turned long-term investor: Chandrakant Sampat tipped him to Gillette; he bought nearly fifteen percent of VST Industries in 2000 at an average of eighty rupees; he accumulated HDFC Bank when its market value was four hundred crore - "Dharavi Dharavi hota hai, aur Pedder Road Pedder Road," he is rumoured to have answered when asked why not a big state bank instead.'),
 p(' Retail entered the plan in 1995. Ramakant Baheti, his finance chief for two decades, says Damani went in "with a view to create something other than stocks to leave behind for the next generation" (' + a(JUGG, 'Forbes India\'s account') + '). He read up on global retailers and concluded that in groceries only the value players - Carrefour, Walmart - had ever achieved scale. Then he did the unfashionable thing: he apprenticed. For the better part of a decade he ran two franchise stores for Apna Bazar, the Mumbai cooperative chain, spending his days in the seven-thousand-square-foot Nerul outlet watching which items moved, how customers behaved, and how much discomfort they would tolerate - he kept the air conditioning low and found they tolerated plenty. The ceiling on the education was structural: sixty percent of the assortment was dictated by Apna Bazar. He wanted his own shelves.'),
]})

G.append({'heading': '2. The store', 'blocks': [
 p(' In 2000 he incorporated Avenue Supermarts. In 2002 the first DMart opened in Powai, followed quickly by Kandivali and Malad - a three-store operation in a city where organized supermarkets were busy dying (' + a(JUGG, 'Forbes India') + '). The mortality around him was the context: India\'s MRP regime forces a retailer to sell at the same printed price in South Mumbai as on the outskirts of Indore, while the kirana across the road runs from owned premises, offers credit, and delivers a single egg. Damani\'s answer to a structural cost disadvantage was to make cost the religion. South Mumbai society thought retailing beneath him; his suppliers met a man in a white shirt, white trousers and sneakers who introduced himself as the purchase manager. Dheeraj Kampani, then a Hindustan Unilever sales supervisor and later DMart\'s buying chief, recalls the disguise and the doctrine: "In retail, everything is science. Assortment is art." And to sellers: "Price mera, quantity tumhara" - I name the price; you decide how much to supply.'),
 p(' The store he built broke the era\'s habits on purpose. No air-conditioned comfort beyond necessity. Racks taken to the ceiling - upper levels for storage, lower for display - so the back room lived in the sales hall. An assortment restricted to what turned fast, tuned by catchment: the Powai store priced five to seven percent above Chandivali\'s because its shoppers would pay it. No loyalty program, because the discount was the loyalty program. And one rule that suppliers still cite first: DMart paid in about eight days where the industry took sixty, in exchange for an upfront discount that was passed straight to the customer (' + a(JUGG, 'the model, in the company\'s own telling to Forbes India') + '). Cash speed became the chain\'s cheapest merchandise.'),
]})

G.append({'heading': '3. The hire', 'blocks': [
 p(' The man who turned that store into a system arrived through the supply side. Neville Noronha had spent eight years at Hindustan Unilever, rising from supervisor to management cadre in modern trade; Damani had watched him across negotiating tables and, in late 2003, asked Kampani to have his boss call. Noronha was conflicted - the competition was the Future Group and RPG at far larger scale - but two things pulled him: at DMart he would deal directly with the owner, and the data said DMart\'s stores had the fastest throughput in the business. His one doubt was whether the model could scale. He signed on in January 2004 and started as head of operations at the Malad store, where the entire company worked out of three desks (' + a(JUGG, 'Forbes India') + ').'),
 p(' His reading of the business became the company\'s doctrine. Price is the differentiator in Indian groceries; margins are wafer-thin, so inventory turns are everything; groceries bring the crowd and general merchandise makes the money - "it\'s the groceries that get shoppers in, but the general merchandise that drives our profits," as Baheti put it. Noronha\'s other conviction was that big ideas are a trap: "I\'ve learnt that big ideas don\'t work... the wins in retail come from relentlessly pursuing small incremental improvements" (' + a(JUGG, 'the Noronha interviews') + '). The founder who loved the store and the operator who loved the system divided the work between them: Damani stayed deep in the business until 2006, mentored young buyers until 2011, and then let the machine run - his only seat in the boardroom passing to his daughter, Manjri Chandak, as a non-executive director.'),
]})

G.append({'heading': '4. The machine', 'blocks': [
 p(' The improvements compounded into an efficiency gap competitors could not close. DMart installed its first ERP platform in 2006, when it had seven stores, and an auto-replenishment system that tracks movement at any store in real time; it opened its first distribution centre in 2011. Rivals built such plumbing after reaching scale; DMart built it to reach scale. It clustered stores across Maharashtra and Gujarat instead of scattering nationally, so the supply chain stayed short. It hired store staff through an agency - "we later hired the better ones," Noronha said - and ran half the employees per square foot of its rivals, per an Ambit Capital note. The payoff, at the time: twenty-nine thousand rupees of sales per square foot, more than twice the competition, and twenty-five days of inventory on hand against Walmart\'s thirty-two globally and Future Retail\'s eighty (' + a(JUGG, 'the operating numbers') + ').'),
 p(' The boldest choice was the floor itself. Indian retail leases; DMart buys. Owning stores is slower and capital-hungry, but it kills the rent line that the MRP regime turns into a death sentence, and it lets the company lay out each store for its catchment. Baheti estimated the company\'s total investment in property and technology at under five hundred crore rupees in two decades - and admitted he and Noronha kept a running contest over who spotted the better locations (' + a(JUGG, 'Forbes India') + '). The first ten years produced just fifty-five stores; the next five took the chain to a hundred and thirty-one across seven states. Slow, then sudden: the throughput came first, the expansion after.'),
]})

G.append({'heading': '5. The sharing', 'blocks': [
 p(' In 2009 Noronha talked Damani into spreading the upside. The employee stock plan that followed was unusually broad: over ninety percent of the staff who joined before the listing held options, and the founder who handpicked his managers made sure the loyalty was paid in equity (' + a(JUGG, 'Forbes India') + '). Damani\'s style was already legendary on the street he came from - after the scams of the nineties he had bought out small investors trapped in worthless positions, and funded community guest houses on condition his name stayed off them (' + a(ETJ, 'the Economic Times\' reporting') + '). Inside his own company the same instinct became policy: the people who built the stores would own a piece of what the stores became.'),
 p(' When the listing came, the sharing showed up in the arithmetic. Noronha held 2.44 percent - worth nine hundred crore rupees on debut - and Baheti 0.57 percent (' + a(BIO, 'Forbes India\'s Rich List reporting') + '). Rakesh Jhunjhunwala, who called Damani his guru and had asked for years when the company would list, got his answer in March 2017. The offer itself was modest - barely ten percent of the company - and the market treated it like a ration: bids came in for nearly a hundred and five times the shares on sale.'),
]})

G.append({'heading': '6. The listing', 'blocks': [
 p(' On 21 March 2017, Avenue Supermarts opened on the BSE at 604.40 rupees against an issue price of 299, touched 650, and closed its first day at 640.75 - up 114.30 percent, the best Indian debut in nearly a decade (' + a(HIND, 'The Hindu\'s market report') + '). At that price the chain was worth nearly forty thousand crore rupees: more than Future Retail, Aditya Birla Fashion and Trent combined, from a base of a hundred and thirty-one stores. Damani\'s 82.2 percent was worth 32,731 crore, and the man who had started at a broker\'s desk at thirty-two overtook Kishore Biyani as the king of Indian retail (' + a(BIO, 'Forbes India') + '). The year behind the debut: revenue of 11,881 crore, up 38.5 percent, and profit of 483 crore, up 51.8 percent - five years of roughly forty percent revenue growth and fifty percent profit growth compounding underneath.'),
 p(' The skeptics had their number too: the stock listed at about fifty-five times forward earnings and touched a hundred and twenty-one times by that October, when it crossed 1,110 rupees (' + a(JUGG, 'the valuation, in context') + '). What the multiple was buying was the model\'s repeatability - every new store the same machine: own the floor, pay in eight days, sell groceries at cost-plus-nothing, take the margin on the merchandise the crowd walks past. And one more thing the roadshow kept circling: the internet. Investors pressed Noronha on online grocery; he answered with the line that would follow him for years - "home deliveries are the fastest way to the graveyard." DMart\'s hedge was DMart Ready, small pickup shops where online orders waited for their owners, at store prices, delivered only for a fee.'),
]})

G.append({'heading': '7. The discipline', 'blocks': [
 p(' Nine years later the machine is still compounding on the same rules. In the year to March 2026, Avenue Supermarts did 66,968 crore rupees of standalone revenue, up 15.9 percent, with 3,224 crore of profit, and crossed five hundred DMart stores in the final quarter (' + a(FY26, 'the company\'s own results release') + '). This past September quarter, revenue grew 17.8 percent on a consolidated basis to 19,644 crore, same-store growth at two-year-old stores improved to 9.5 percent, customers signed 11.1 crore bills, and the network reached 518 stores (' + a(Q2, 'the Q2 FY27 scorecard') + '). The eight-day supplier rule, the owned floors, the ceiling-high racks: unchanged.'),
 p(' The two newest facts are the ones a founder would find hardest. First, the company now changes hands calmly: the board named Anshul Asawa CEO-designate in January 2025, and on 1 February 2026 he succeeded Noronha as managing director and CEO - a date fixed a year in advance, in writing, without drama (' + a(NSE, 'the exchange filing') + '). Second, the company is retreating where it once only advanced: DMart Ready, the e-commerce arm, has been deliberately pulled back from nineteen cities to eleven, refocused on metros and home delivery, because the economics said so (' + a(Q2, 'the investor update') + '). The man who called home delivery a graveyard would recognize the logic; the company he built no longer needs him to apply it. That is what a machine is for. Somewhere in Mumbai there is still a purchase manager checking the racks - only now there are five hundred and eighteen stores, and the discipline, not the man, does the checking.'),
]})

d = json.load(open('editions-src/longreads.json'))
d['43'] = lr
json.dump(d, open('editions-src/longreads.json','w'), indent=1, ensure_ascii=False)
print('LR43 written:', sum(len(g['blocks']) for g in G), 'blocks,',
      sum(len(b['html'].split()) for g in G for b in g['blocks']), 'words')
